// node 3ds/tests/make_font.mjs > 3ds/source/font_glyphs.h
// C glyph table for the pixel-font atlas (assets/fonts/casino-run-pixel-atlas.*), shared with the web.
import fs from "node:fs";
const { cell, glyphs } = JSON.parse(fs.readFileSync(new URL("../../assets/fonts/casino-run-pixel-atlas.json", import.meta.url), "utf8"));
const esc = (c) => (c === "'" || c === "\\" ? `'\\${c}'` : `'${c}'`);
const rows = Object.entries(glyphs).map(([c, g]) => `  { ${esc(c)}, ${g.x}, ${g.y}, ${g.w} },`);
process.stdout.write([
  "// Generated by 3ds/tests/make_font.mjs from casino-run-pixel-atlas.json. Do not edit.",
  "typedef struct { char c; unsigned char x, y, w; } cr_glyph;",
  `enum { CR_FONT_CELL_W = ${cell[0]}, CR_FONT_CELL_H = ${cell[1]}, CR_GLYPH_COUNT = ${rows.length} };`,
  "static const cr_glyph CR_GLYPHS[CR_GLYPH_COUNT] = {",
  ...rows,
  "};",
  "",
].join("\n"));
